import { type Page, test } from "@playwright/test";

import * as ui from "@e2e/ui-actions";

type ActivateSkillModeOptions = {
  userMessage: string;
  /** When the first turn only acknowledges intent, a second send often triggers `activate`. */
  followUpMessage?: string;
  expectedWelcomeSkill: string;
  /** Lifecycle row expected in the log once routing settles (may differ from the header). */
  expectedSkill: string;
  /** Skill pane header after the turn(s); defaults to `expectedSkill`. */
  expectedActiveSkill?: string;
  /** When LLM routing can legitimately settle on more than one active skill. */
  expectedActiveSkillCandidates?: string[];
};

export const activateSkillMode = async (
  page: Page,
  options: ActivateSkillModeOptions,
): Promise<void> => {
  await test.step(`Switch to Inspect mode and assert "${options.expectedWelcomeSkill}" is active`, async () => {
    await ui.inspectorShell.actions(page).toggleInspectOn();
    await ui.conversationLog.assertions(page).agentTurnEndedCountAtLeast(1);
    await ui.skillSection.assertions(page).skillDocumentIsVisible();
    await ui.skillSection.assertions(page).activeSkillNameIs(options.expectedWelcomeSkill);
  });

  await test.step(`Send "${options.userMessage}" and assert "${options.expectedSkill}" is active`, async () => {
    await ui.conversationLog
      .actions(page)
      .completeTurn(() => ui.inspectorShell.actions(page).sendMessage(options.userMessage));

    const followUpMessage = options.followUpMessage;
    if (followUpMessage) {
      await ui.conversationLog
        .actions(page)
        .completeTurn(() => ui.inspectorShell.actions(page).sendMessage(followUpMessage));
    }

    // Log rows settle before the skill pane header; both are required so we do
    // not assert toggles while routing is still mid-turn.
    await ui.conversationLog
      .assertions(page)
      .lifecycleRowIsVisible(`${options.expectedSkill} skill activated`);
    const activeSkill = options.expectedActiveSkill ?? options.expectedSkill;
    if (options.expectedActiveSkillCandidates) {
      await ui.skillSection
        .assertions(page)
        .skillHeaderIsOneOf(options.expectedActiveSkillCandidates);
    } else {
      await ui.skillSection.assertions(page).skillHeaderShows(activeSkill);
    }
  });
};

const DISAMBIGUATION_ACTIVATED = "Card Disambiguation skill activated";

/** Card Replace → Card Disambiguation routing for conversation-log specs. */
export const activateCardDisambiguationRouting = async (
  page: Page,
  options: {
    expectedWelcomeSkill: string;
    replaceMessage: string;
    /** Sent only when the first turn does not surface disambiguation activation. */
    recoveryPickMessage: string;
  },
): Promise<void> => {
  await test.step(`Switch to Inspect mode and assert "${options.expectedWelcomeSkill}" is active`, async () => {
    await ui.inspectorShell.actions(page).toggleInspectOn();
    await ui.conversationLog.assertions(page).agentTurnEndedCountAtLeast(1);
    await ui.skillSection.assertions(page).skillDocumentIsVisible();
    await ui.skillSection.assertions(page).activeSkillNameIs(options.expectedWelcomeSkill);
  });

  await test.step(`Route "${options.replaceMessage}" through Card Disambiguation`, async () => {
    await ui.conversationLog
      .actions(page)
      .completeTurn(() => ui.inspectorShell.actions(page).sendMessage(options.replaceMessage));

    const disambiguationRow = ui.conversationLog
      .getLocators(page)
      .conversationEvents.getByText(DISAMBIGUATION_ACTIVATED)
      .first();
    if (!(await disambiguationRow.isVisible())) {
      await ui.conversationLog
        .actions(page)
        .completeTurn(() =>
          ui.inspectorShell.actions(page).sendMessage(options.recoveryPickMessage),
        );
    }

    await ui.conversationLog.assertions(page).lifecycleRowIsVisible(DISAMBIGUATION_ACTIVATED);
    await ui.skillSection
      .assertions(page)
      .skillHeaderIsOneOf(["Card Disambiguation", "Card Replace"]);
  });
};
